% Lab 6 - Variant 3
% Duru Ozturk
% Task 2: passing data with global variables

clc;

global x y                     

x = 2*pi : -0.2 : -2*pi;       
y = zeros(size(x));             

negative_part                  
positive_part                  

whos                            %[output:4a6f411c]

plot(x, y, 'k-.+');              %[output:90db1671]
grid on %[output:90db1671]
xlabel('x') %[output:90db1671]
ylabel('y(x)') %[output:90db1671]
title('y = -sin(x) for x < 0, y = sin(x) for x >= 0') %[output:90db1671]

